"""A small LRU cache."""

from collections import OrderedDict


class LRUCache:
    """A cache with a fixed capacity that evicts the least recently used item.

    Reads (``get``) and writes (``put``) both count as a "use" of the key,
    so the item touched least recently is the one that gets evicted when the
    cache is full.  Membership tests (``in``) and ``len`` do not affect
    recency.
    """

    def __init__(self, capacity):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self.capacity = capacity
        self._data = OrderedDict()

    def get(self, key, default=None):
        """Return the value for *key*, marking it most recently used.

        If *key* is not present, *default* is returned (``None`` by default)
        and nothing about the cache state changes.
        """
        try:
            self._data.move_to_end(key)
        except KeyError:
            return default
        return self._data[key]

    def put(self, key, value):
        """Insert or update *key*, marking it most recently used.

        Updating an existing key never evicts anything.  Inserting into a
        full cache evicts the least recently used item first.
        """
        if key in self._data:
            self._data[key] = value
            self._data.move_to_end(key)
            return
        if len(self._data) >= self.capacity:
            self._data.popitem(last=False)
        self._data[key] = value

    def __len__(self):
        return len(self._data)

    def __contains__(self, key):
        return key in self._data

    def __repr__(self):
        return "LRUCache({!r})".format(dict(self._data))
